import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.Dg5fKO7V.js";const g=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"Getting-Started.md","filePath":"Getting-Started.md","lastUpdated":1788563284000}'),i={name:"Getting-Started.md"};function r(s,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="the-first-launch" tabindex="-1">The first launch <a class="header-anchor" href="#the-first-launch" aria-label="Permalink to &quot;The first launch&quot;">​</a></h2><p>Three things happen in order, and only the first one holds the app up.</p><p><strong>The catalogue arrives.</strong> A single file from the manami project, giving titles, synonyms, covers and the bridge between AniList and MyAnimeList ids. Under a minute on a normal connection. The startup screen shows this one because there is nothing to browse without it.</p><p><strong>You make a profile.</strong> A name and a picture. Everything you watch, rate and save belongs to a profile, and a profile never leaves your machine.</p><p><strong>Metadata arrives with what you are looking at.</strong> Descriptions, characters, banners, airing dates and episode counts come from AniList, for the titles on your screen and no others. Opening the home screen costs one request, and every card it drew is fetched together shortly after, so the page you open next is already there.</p><p>There is no catalogue-wide pass and nothing to wait for. What you have already looked at is kept, up to a ceiling, so a second visit costs nothing at all.</p><h2 id="finding-something-to-watch" tabindex="-1">Finding something to watch <a class="header-anchor" href="#finding-something-to-watch" aria-label="Permalink to &quot;Finding something to watch&quot;">​</a></h2><ul><li><strong>Search</strong> with <code>Ctrl</code>/<code>Cmd</code> + <code>K</code> from anywhere. It searches the local catalogue, so it answers instantly and works offline. Promotional clips, music videos and Chinese animation are omitted; visible pages are checked against the already requested AniList metadata before they appear.</li><li><strong>Trending, Popular, Top rated and Upcoming</strong> are on the home page.</li><li><strong>Seasonal</strong> shows what is airing now, and lets you walk to other years.</li><li><strong>Genres</strong> gives a wall of one cover per genre.</li><li>Hovering a card opens a preview with the description, the score and, when there is one, the trailer.</li></ul><h2 id="watching" tabindex="-1">Watching <a class="header-anchor" href="#watching" aria-label="Permalink to &quot;Watching&quot;">​</a></h2><p>Open a title and press Watch, or use the Watch button on the hover preview to skip the detail page.</p><p>The player has opening and ending skip when <a href="https://aniskip.com" target="_blank" rel="noreferrer">AniSkip</a> has timestamps for the episode, auto-play next, speed control, and a track selector for subtitled or dubbed.</p><p>Use the dedicated play button or press <code>Space</code> or <code>K</code> without a command modifier to toggle playback. <code>Ctrl</code>/<code>Cmd</code> + <code>K</code> still opens search while watching and does not also pause the video. Keyboard shortcuts are listed from the help button in the player.</p><h2 id="building-a-library" tabindex="-1">Building a library <a class="header-anchor" href="#building-a-library" aria-label="Permalink to &quot;Building a library&quot;">​</a></h2><p>Every title has five states: watching, completed, plan to watch, on hold and dropped. Progress is recorded as you watch, so continue-watching on the home page stays correct without any bookkeeping.</p><p><strong>Offline</strong> cuts across those states and shows what is downloaded to this machine. <strong>Top lists</strong> are your own ordered lists, separate from the watch states.</p><p><strong>Importing.</strong> Settings has an import for a public AniList or MyAnimeList list. Matching is by id, so nothing is guessed.</p><h2 id="profiles" tabindex="-1">Profiles <a class="header-anchor" href="#profiles" aria-label="Permalink to &quot;Profiles&quot;">​</a></h2><p>Several profiles share one installation and one catalogue, but nothing else. Switching profiles stops playback cleanly and lands on that profile&#39;s home page.</p><h2 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h2><p>Any episode can be downloaded, and its metadata and artwork are stored beside it, so a downloaded show stays browsable with no connection at all. Downloads go where you choose, everything else stays in the application data directory.</p><h2 id="when-something-looks-wrong" tabindex="-1">When something looks wrong <a class="header-anchor" href="#when-something-looks-wrong" aria-label="Permalink to &quot;When something looks wrong&quot;">​</a></h2><p>See <a href="./Troubleshooting">Troubleshooting</a>. The connectivity board under Settings checks every source live from your own machine and is usually the fastest way to see what is actually down.</p>',23)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
